const ctx = $('When Called').first().json;
const minScore = ctx.clinic?.pinecone_min_score ?? 0.78;
const docs = $input.all();

let maxScore = 0;
const chunks = [];
for (const d of docs) {
  const j = d.json || {};
  const score = j.score ?? j.document?.score ?? (j.metadata?.score) ?? null;
  if (typeof score === 'number' && score > maxScore) maxScore = score;
  const text = j.pageContent ?? j.document?.pageContent ?? j.text ?? '';
  if (text) chunks.push(text);
}

// If no numeric score is exposed by this n8n version, fall back to 'found if any chunk returned'.
const scoreKnown = maxScore > 0;
const found = scoreKnown ? (maxScore >= minScore) : (chunks.length > 0);

return [{ json: {
  ...ctx,
  faq_found: found,
  faq_max_score: maxScore,
  faq_chunks: chunks.slice(0, 5).join('\n---\n')
} }];

const ctx = $('When Called').item.json;
const answer = $json.text || $json.output || 'I can help with that — let me connect you with our team to be sure.';
return { json: { ...ctx, bot_response: answer } };

